script:
frappe.ui.form.on("Payment Request", {
	refresh(frm) {
		if (frm.is_new() || frm.doc.docstatus !== 0) {
			return;
		}

		frm.add_custom_button(
			__("Copy approval link"),
			() => {
				const path = `/app/payment-request/${encodeURIComponent(frm.doc.name)}`;
				const url = `${window.location.origin}${path}`;
				frappe.utils.copy_to_clipboard(url);
				frappe.show_alert({
					message: __(
						"Link copied. Send to the next approver via IM (login and approver role required)."
					),
					indicator: "green",
				});
			},
			__("Share")
		);

		// 根因：frappe/form/toolbar.js 中 can_submit() 要求 !has_workflow()，有工作流时工具栏永远不会设「Submit」；终态又无 transition，主按钮处于空/隐藏。
		// 在审批完成（COS PR Approved）且具备 submit 权限时，显式恢复与 Toolbar 相同的 Save/Submit 行为。
		if (frm.doc.workflow_state !== "COS PR Approved") {
			return;
		}
		if (!frm.perm?.[0]?.submit) {
			return;
		}
		setTimeout(() => {
			if (frm.is_new() || frm.doc.docstatus !== 0) {
				return;
			}
			if (frm.doc.workflow_state !== "COS PR Approved") {
				return;
			}
			if (!frm.perm?.[0]?.submit) {
				return;
			}
			if (frm.doc.__unsaved) {
				frm.page.set_primary_action(__("Save"), function () {
					return frm.save("Save", null, this);
				});
				return;
			}
			frm.page.set_primary_action(__("Submit"), function () {
				return frm.savesubmit(this);
			});
		}, 350);
	},
});

